// Probe — capture des échecs rouges réels pour .scratch/to_fix.md.
// Logique pure, sans DOM. Cette sonde est supprimée après capture.
import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  ballSpeed,
  BALL_R,
  PADDLE_Y,
  BRICK_TOP,
  BRICK_H,
  BRICK_W,
} from '../game/neon.js';

// --- helpers ---------------------------------------------------------------

// brique (row, col) de la grille du niveau 1
function brick(state, row, col) {
  return state.bricks[row * 8 + col];
}

// --- D1 : aucun rebond sur les briques -------------------------------------

test('D1: ball bouncing off the underside of a brick flips vy and kills it', () => {
  const state = createState(1);
  const b = brick(state, 0, 3); // [244,316] x [48,68]
  state.ball = { x: 280, y: b.y + BRICK_H + 6, r: BALL_R, vx: 0, vy: -300 };
  step(state, 1 / 60); // moves 5px up: y 74 -> 69, overlapping the bottom face
  assert.equal(b.alive, false, 'the brick must die');
  assert.ok(state.ball.vy > 0, 'vy must flip from up (-300) to down');
});

// --- D2 : traversée (tunneling) au niveau 6+ -------------------------------

test('D2: head-on pass longer than brick height + diameter still bounces (level 6, dt=0.05)', () => {
  const state = createState(6);
  const b = brick(state, 0, 3); // [244,316] x [48,68]
  // Ball starts 14.5px below the brick, ends 8px above it: 35.5px > 34px,
  // so a discrete end-of-step check never sees an overlap.
  state.ball = { x: 280, y: b.y + BRICK_H + BALL_R + 0.5, r: BALL_R, vx: 0, vy: -ballSpeed(6) };
  step(state, 0.05); // displacement 35.5
  assert.equal(b.alive, false, 'the brick must die');
  assert.ok(state.ball.vy > 0, 'vy must flip: the ball bounces off even at 35.5px per step');
});

// --- D3 : collant (recouvrement non résolu) --------------------------------

test('D3: deep penetration is resolved: the ball ends up outside the brick, on the side it came from', () => {
  const state = createState(1);
  const b = brick(state, 0, 3); // [244,316] x [48,68]
  // Ball fully inside the brick, moving up: it entered through the bottom face.
  state.ball = { x: 280, y: b.y + BRICK_H - 8, r: BALL_R, vx: 0, vy: -300 };
  step(state, 1 / 60);
  assert.ok(state.ball.vy > 0, 'vy flips');
  assert.ok(
    state.ball.y + state.ball.r >= b.y + BRICK_H,
    'the ball must be pushed out below the bottom face (y+r >= 68), got ' + (state.ball.y + state.ball.r)
  );
  assert.equal(collides(state.ball, b), false, 'no overlap may remain after resolution');
});

// --- D4 : double inversion sur couture (seam / ghost collision) ------------

test('D4: ball straddling the seam between two side-by-side bricks bounces ONCE (vy > 0), both bricks die', () => {
  const state = createState(1);
  const a = brick(state, 0, 3); // [244,316]
  const c = brick(state, 0, 4); // [324,396]
  // Ball centered in the 8px gap (x=320), spans [313,327]: 3px into each brick.
  state.ball = { x: 320, y: 64, r: BALL_R, vx: 0, vy: -300 };
  step(state, 1 / 60); // y 64 -> 59, still straddling both
  assert.equal(a.alive, false, 'left brick dies');
  assert.equal(c.alive, false, 'right brick dies');
  assert.ok(state.ball.vy > 0, 'exactly one bounce: vy ends positive (down), not double-flipped back up');
});

// --- D5 : face vs coin -----------------------------------------------------

test('D5a: side hit flips vx only, vy is untouched', () => {
  const state = createState(1);
  const b = brick(state, 0, 3); // [244,316] x [48,68]
  // Ball 4px into the left face, moving right-up.
  state.ball = { x: b.x - BALL_R + 3, y: 58, r: BALL_R, vx: 300, vy: -100 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx < 0, 'vx flips (was 300)');
  assert.equal(state.ball.vy, -100, 'vy stays -100: a side hit does not touch the vertical axis');
  assert.equal(collides(state.ball, b), false, 'ball is pushed out of the brick');
});

test('D5b: corner hit (equal penetration on both axes) flips BOTH velocities', () => {
  const state = createState(1);
  const b = brick(state, 0, 3); // [244,316] x [48,68]
  // Ball 3px right of the left edge AND 3px below the bottom edge: a corner.
  state.ball = { x: b.x - BALL_R + 3, y: b.y + BRICK_H + BALL_R - 4, r: BALL_R, vx: 300, vy: -300 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx < 0, 'vx flips on a corner');
  assert.ok(state.ball.vy > 0, 'vy flips on a corner');
  assert.equal(collides(state.ball, b), false, 'ball is pushed out of the corner');
});

// --- D6 : paddle traversé par le haut à grande vitesse ---------------------

test('D6: fast ball crossing the paddle band in one step still bounces off its top (level 7, dt=0.05)', () => {
  const state = createState(7);
  // 40px step: the ball jumps from fully above to fully below the 12px band.
  state.ball = { x: 320, y: PADDLE_Y - BALL_R - 6, r: BALL_R, vx: 0, vy: ballSpeed(7) };
  step(state, 0.05); // y 435 -> 475; bottom edge 442 -> 482
  assert.ok(state.ball.vy < 0, 'vy must flip: the ball bounces off the paddle');
  assert.ok(state.ball.y < PADDLE_Y, 'the ball ends above the paddle, got y=' + state.ball.y);
});

// --- D7 : angle mort (contact au centre du paddle -> vx = 0) ----------------

test('D7: dead-center paddle hit never leaves a zero vx (no vertical soft-lock)', () => {
  const state = createState(1);
  state.ball = { x: state.paddle.x + state.paddle.w / 2, y: PADDLE_Y - BALL_R - 1, r: BALL_R, vx: 0, vy: 300 };
  step(state, 1 / 60);
  assert.ok(Math.abs(state.ball.vx) >= 0.25 * ballSpeed(1), '|vx| must stay >= 0.25*speed, got ' + state.ball.vx);
});

// --- D8 : vitesse (norme non conservée au rebond paddle) -------------------

test('D8: paddle rebound keeps the level speed (norm == ballSpeed)', () => {
  const state = createState(1);
  const s = ballSpeed(1);
  state.ball = { x: state.paddle.x, y: PADDLE_Y - BALL_R - 1, r: BALL_R, vx: 0, vy: 300 };
  step(state, 1 / 60); // edge hit: hit factor -1
  const norm = Math.hypot(state.ball.vx, state.ball.vy);
  assert.ok(Math.abs(norm - s) < 1e-9, 'norm after paddle rebound must equal level speed ' + s + ', got ' + norm);
});

// --- D9 : transitions (dernière brique + dernière vie dans la même frame) --

test('D9: a cleared level is credited even when the ball is lost the same frame', async () => {
  const { settle } = await import('../game/neon.js'); // does not exist yet -> red
  const state = createState(1);
  state.lives = 1;
  state.bricks = state.bricks.map((b) => ({ ...b, alive: false }));
  settle(state, true); // ball lost, grid empty
  assert.equal(state.level, 2, 'the level is won, not restarted');
  assert.equal(state.lives, 1, 'no life is spent on an already-won level');
  assert.ok(state.bricks.some((b) => b.alive), 'a fresh grid for level 2 is in place');
});

test('D9b: a lost ball with bricks still standing consumes a life', async () => {
  const { settle } = await import('../game/neon.js');
  const state = createState(1);
  state.lives = 2;
  settle(state, true);
  assert.equal(state.lives, 1);
});

