```

settle():
```js
// End-of-frame bookkeeping: a cleared level is credited BEFORE the loss is
// processed, so destroying the last brick and losing the ball in the same
// frame never swallows the win. Pure (storage is optional; used only by the
// game-over branch). Returns the state.
export function settle(state, lost, storage = null) {
  // Level cleared: all bricks broken — credit the win even if the ball is
  // lost the same frame (no life is spent on an already-won level).
  if (state.bricks.every((b) => !b.alive)) {
    state.level += 1;
    state.bricks = makeBricks(state.level);
    state.ball = createState(state.level).ball;
    return state;
  }

  if (lost) {
    state.lives -= 1;
    state.combo = 0;
    if (state.lives <= 0) {
      state.best = saveBest(storage, state.score);
      Object.assign(state, createState(state.level));
      state.best = loadBest(storage);
    } else {
      // relaunch the ball
      state.ball = createState(state.level).ball;
    }
  }
  return state;
}
```

