function sweptCrosses(ball, px, py, brick) {
  const x0 = brick.x - ball.r;
  const x1 = brick.x + brick.w + ball.r;
  const y0 = brick.y - ball.r;
  const y1 = brick.y + brick.h + ball.r;
  let tEnter = 0;
  let tExit = 1;
  const slabs = [
    [px, ball.x, x0, x1],
    [py, ball.y, y0, y1],
  ];
  for (const [start, end, lo, hi] of slabs) {
    const delta = end - start;
    if (delta === 0) {
      if (start < lo || start > hi) return false; // parallel and outside
    } else {
      let t1 = (lo - start) / delta;
      let t2 = (hi - start) / delta;
      if (t1 > t2) [t1, t2] = [t2, t1];
      tEnter = Math.max(tEnter, t1);
      tExit = Math.min(tExit, t2);
      if (tEnter > tExit || tExit < 0) return false;
    }
  }
  return tEnter < 1;
}

// --- Score & combo (NOT covered by tests — debt #5) ------------------------

// Combo multiplier. UNBOUNDED today: a long combo makes the score blow up
// uncontrollably (see #5, expected improvement = clamp it).
export function comboMultiplier(combo) {
  return 1 + combo * 0.5;
}

// Points earned for breaking a brick, combo included.
export function scoreForBrick(brick, combo) {
  return Math.round(brick.points * comboMultiplier(combo));
}

// --- Best score persistence ------------------------------------------------

// Reads the best score from a localStorage-compatible storage.
// Robust to corrupted or missing storage: returns 0 instead of throwing.
export function loadBest(storage) {
  if (!storage) return 0;
  try {
    const raw = storage.getItem(STORAGE_KEY);
    const value = Number.parseInt(raw, 10);
    return Number.isFinite(value) && value > 0 ? value : 0;
  } catch {
    return 0;
  }
}

// Writes the best score if the current score beats it. Returns the updated best.
export function saveBest(storage, score) {
  const best = loadBest(storage);
  if (score > best && storage) {
    try {
      storage.setItem(STORAGE_KEY, String(score));
    } catch {
      // storage unavailable (private mode, quota): silently ignore
    }
    return score;
  }
  return best;
}

// --- Physics (movement + wall/paddle bounces) ------------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Start of the step: the brick collision below is swept across the segment
  // (prevX, prevY) -> (ball.x, ball.y), so a step longer than an obstacle
  // cannot tunnel through it.
  const prevX = ball.x;
  const prevY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle: swept band test — the ball's bottom edge travelled from
  // prevY + r to ball.y + r during this step, and bounces when that segment
  // crosses the band [paddle.y, paddle.y + paddle.h]. A step longer than the
  // band (12 + 14 = 26px, from level 4 at dt=50ms) can no longer skip it.
  if (
    ball.vy > 0 &&
    prevY + ball.r <= paddle.y + paddle.h &&
    ball.y + ball.r >= paddle.y &&
    ball.x + ball.r >= paddle.x &&
    ball.x - ball.r <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    const speed = ballSpeed(state.level);
    // The rebound angle depends on where the paddle was hit.
    const hit = Math.max(-1, Math.min(1, (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2)));
    // Dead angle: a dead-center hit (hit = 0) would send the ball straight up
    // with vx = 0 — an unplayable vertical loop. Keep the rebound off the
    // vertical by flooring |vx| at 25% of the level speed.
    let vx = speed * 0.6 * hit;
    if (Math.abs(vx) < 0.25 * speed) vx = Math.sign(vx || 1) * 0.25 * speed;
    ball.vx = vx;
    // Speed conservation: the rebound leaves the ball at exactly the level
    // speed, so the ball neither speeds up nor dies over the exchanges.
    ball.vy = -Math.sqrt(Math.max(speed * speed - vx * vx, 0));
    state.combo = 0; // touching the paddle resets the combo
  }

  // Bricks: kill on contact and bounce — one resolution per pass.
  // Detection is swept: the travel segment from (prevX, prevY) to the current
  // position is tested against each brick, so a step longer than the brick
  // (ballSpeed x dt > BRICK_H + 2*BALL_R, from level 6 at dt=50ms) still
  // bounces instead of tunneling.
  const hitBricks = [];
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    if (collides(state.ball, brick) || sweptCrosses(ball, prevX, prevY, brick)) {
      hitBricks.push(brick);
    }
  }
  if (hitBricks.length > 0) {
    for (const brick of hitBricks) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }
    // One bounce per pass, on the velocity-dominant axis, then push the ball
    // out of the brick it hit so no overlap remains (no sticking).
    const b = hitBricks[0];
    if (Math.abs(ball.vx) === Math.abs(ball.vy)) {

